/// Crate version, from the workspace.
pub const VERSION: &str = env!("CARGO_PKG_VERSION");

/// The engine id, re-exported so a benchmark report does not have to import
/// from two crates.
pub const ENGINE_ID: &str = engine::HeuristicDiarizer::ID;

/// A one-line statement of what this build actually provides.
///
/// Printed by `vaani doctor` and recorded in the benchmark report, because
/// "diarization" on its own does not tell a reader whether the speaker labels
/// came from a trained model or from this crate's spectral heuristic. The
/// distinction matters: a user comparing DER numbers across two machines must
/// be able to tell whether the two runs used the same method.
#[must_use]
pub fn capability_statement() -> String {
    format!(
        "{} {} — spectral-heuristic speaker separation (cepstral + pitch, agglomerative \
         clustering). No trained speaker embedder is installed, so no diarization error \
         rate is claimed.",
        ENGINE_ID, VERSION
    )
}
